import{d as p,C as n,o as d,c as g,a3 as s,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十章","description":"《正易心法》第十章——粤乾与坤，即是阴阳：乾坤纯而不驳、圆融合粹，引《老子》「天得一以清，地得一以宁」印证；尽乾之道为圣，尽坤之道为贤。","frontmatter":{"title":"正易心法·第十章","description":"《正易心法》第十章——粤乾与坤，即是阴阳：乾坤纯而不驳、圆融合粹，引《老子》「天得一以清，地得一以宁」印证；尽乾之道为圣，尽坤之道为贤。","category":"guide","aliases":["正易心法第十章","粤乾与坤即是阴阳","纯而不驳"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-10.md","filePath":"yijing/zheng-yi-xin-fa/chapter-10.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-10.md"},x=p({...c,setup(u){const o=[{id:"z10-01",label:"一、乾坤即是阴阳",showLabel:!0,sentences:[["粤乾与坤，即是阴阳。",{text:"圆融",glossary:"yuanrong"},"合粹，平和之中。"]],note:["「粤」是句首发语词。乾与坤，就是阴阳本身——圆满融通、纯粹合一，处于平和之中。（注意「即是」二字：乾坤不是阴阳的「象征」，而是阴阳本身的卦画写照。这一点与《系辞传》「乾，阳物也；坤，阴物也」的说法有细微不同——后者说乾坤是阴阳的「物」，麻衣直接说乾坤「就是」阴阳。）"]},{id:"z10-02",label:"二、纯而不驳",showLabel:!0,sentences:[["凡阴阳之气，纯而不驳，是为乾坤。"]],note:["凡是阴阳之气，纯粹而不驳杂，就是乾坤。（「驳」是杂乱不纯。与第九章合读更清楚：乾坤各守其纯，是本体；一旦异类爻混入，纯被打破，即成六子——**纯（乾坤）→ 破体 → 驳（六子）→ 万物化生**，这是从本体到现象的生成过程。）"]},{id:"z10-03",label:"三、老子得一",showLabel:!0,sentences:[["《老子》曰：“天",{text:"得一",glossary:"deyi"},"以清，地得一以宁。”正谓此也。"]],note:["《老子》说：「天得一而清明，地得一而安宁。」说的正是这个道理。（《老子》三十九章原文后面还有「神得一以灵，谷得一以盈，万物得一以生，侯王得一以为天下正」。这里的「一」不是数字 1，而是**纯粹、完整、不驳杂的本性**——天得一就是乾守纯阳，地得一就是坤守纯阴。这是本书唯一一次引用道家经典，也正是陈抟一脉「以道解易」的思想标记。）"]},{id:"z10-04",label:"四、圣贤各尽乾坤",showLabel:!0,sentences:[["因知能尽乾之道，是为圣人；能尽坤之道，是为贤人。"]],note:["由此可知：能完全体现乾之道的，是圣人；能完全体现坤之道的，是贤人。（这里没有「圣人高于贤人」的意思——**圣人尽乾（纯阳之德：刚健、创造、光明），贤人尽坤（纯阴之德：柔顺、承载、厚德），是两种完整的、并列的人格**。这里的「尽」是关键：不是「靠近」，而是「完全体现而不驳杂」；驳杂（既非纯阳也非纯阴）才是普通人的状态。）"]}],i=[{id:"yuanrong",term:"圆融",pinyin:"yuán róng",meaning:"圆满融通，无所滞碍。阴阳之气运行无碍。"},{id:"deyi",term:"得一",pinyin:"dé yī",meaning:"《老子》三十九章语。此处「一」不是数字，而是纯粹、完整、不驳杂的本性：天得一即乾守纯阳，地得一即坤守纯阴。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return d(),g("div",null,[t[0]||(t[0]=s("",28)),e(r,{colophon:"即是阴阳 · 纯而不驳 · 天得一以清 · 圣贤各尽",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十章原文",sections:o,glossary:i}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如句首「粤」为发语词），不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"即是阴阳",pinyin:["jí","shì"],meaning:"「即是」二字是关键：乾坤不是阴阳的象征，而是阴阳本身的卦画写照。"},{term:"纯而不驳",pinyin:["chún","ér"],meaning:"纯粹而不驳杂。乾坤各守其纯，是本体；一旦异类爻混入即成六子。"},{term:"得一",pinyin:["dé","yī"],meaning:"《老子》三十九章：「天得一以清，地得一以宁。」此「一」非数字，而是纯粹完整不驳杂的本性。"},{term:"尽乾之道为圣",pinyin:["jìn","qián"],meaning:"完全体现刚健创造之德即是圣人。与「尽坤之道为贤」并列，非高下之分，关键在「纯」。"},{term:"回望本源",pinyin:["huí","wàng"],meaning:"在展开六子、六十四卦之前，先回看乾坤的纯粹状态——这是一切的起点，也是一切的归宿。"}]}),t[3]||(t[3]=s("",24))])}}});export{y as __pageData,x as default};
